#!/usr/bin/env sh
set -eu
SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd); ROOT=$(CDPATH= cd -- "$SCRIPT_DIR/../.." && pwd); REPO_ROOT=$(CDPATH= cd -- "$ROOT/.." && pwd); service=${1:?Usage: build-image.sh <service> <image-tag>}; tag=${2:?Usage: build-image.sh <service> <image-tag>}; IMAGE_PREFIX=${IMAGE_PREFIX:-localhost:5000/peach-cloud}
launch_dir() { case "$1" in peach-gateway) echo "peach-gateway/peach-gateway-launch" ;; peach-auth) echo "peach-auth/peach-auth-launch" ;; peach-monitor) echo "peach-monitor/peach-monitor-launch" ;; peach-fileservice) echo "peach-fileservice/peach-fileservice-launch" ;; peach-message) echo "peach-message/peach-message-launch" ;; peach-setting) echo "peach-setting/peach-setting-launch" ;; peach-generator) echo "peach-generator/peach-generator-launch" ;; peach-scheduled) echo "peach-scheduled/peach-scheduled-launch" ;; *) echo "Unsupported backend service: $1" >&2; exit 1 ;; esac; }
module=$(launch_dir "$service"); jar=$(find "$REPO_ROOT/$module/target" -maxdepth 1 -type f -name '*.jar' ! -name '*-sources.jar' ! -name '*-javadoc.jar' ! -name '*.original' | head -n 1); [ -n "$jar" ] || { echo "No runnable jar found for $service" >&2; exit 1; }
context="$ROOT/runtime/generated/build-context/$service"; rm -rf "$context"; mkdir -p "$context"; cp "$jar" "$context/app.jar"
docker build --build-arg JAR_FILE="runtime/generated/build-context/$service/app.jar" --build-arg IMAGE_TITLE="$service" --build-arg IMAGE_DESCRIPTION="Peach Cloud $service" --build-arg IMAGE_AUTHORS="${IMAGE_AUTHORS:-Mr Shu}" --build-arg IMAGE_VENDOR="${IMAGE_VENDOR:-Peach Cloud}" --build-arg IMAGE_VERSION="$tag" --build-arg IMAGE_REVISION="$tag" -f "$ROOT/images/service/Dockerfile" -t "$IMAGE_PREFIX/$service:$tag" "$ROOT"
